import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    h = int(input[ptr])
    ptr += 1
    u = list(map(int, input[ptr:ptr+n]))
    ptr += n
    clients = []
    for _ in range(m):
        c1 = int(input[ptr])
        c2 = int(input[ptr+1])
        clients.append((c1-1, c2-1))
        ptr += 2

    def is_valid(subset):
        new_u = u.copy()
        for idx in subset:
            new_u[idx] = (new_u[idx] + 1) % h
        for c1, c2 in clients:
            if new_u[c1] == new_u[c2]:
                return False
        return True

    min_k = float('inf')
    best_subset = None

    for k in range(1, n+1):
        from itertools import combinations
        for subset in combinations(range(n), k):
            if is_valid(subset):
                if k < min_k:
                    min_k = k
                    best_subset = subset
                    if min_k == 1:
                        break
        if min_k == 1:
            break

    print(min_k)
    print(' '.join(str(x+1) for x in best_subset))

if __name__ == '__main__':
    main()
